=== build_velaguard_mbslave.ps1 ===
﻿# Build Modbus Slave workspace for VelaGuard 32-slave mock bus.
# Requires Modbus Slave (Mbslave.Application COM) on Windows.
#
# Usage (PowerShell):
#   .\scripts\build_velaguard_mbslave.ps1
#   .\scripts\build_velaguard_mbslave.ps1 -OpenConnection -KeepOpen
#   .\scripts\build_velaguard_mbslave.ps1 -OpenConnection -KeepOpenSeconds 3600
#
# Output: %USERPROFILE%\Documents\mthings\NN_<sensor>.mbs
#   e.g. 01_温湿度-导轨V1.5.mbs  (names from velaguard.mthings / CSV)

param(
  [int]$ComPort = 6,
  [int]$Baud = 9600,
  [switch]$OpenConnection,
  [switch]$ShowWindows,
  [switch]$KeepOpen,
  [int]$KeepOpenSeconds = 0,
  [string]$OutDir = "$env:USERPROFILE\Documents\mthings"
)

$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $repoRoot "config\modbus-slave\velaguard_slaves.csv"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

if (-not (Test-Path $csvPath)) {
  throw "Missing $csvPath — run export from velaguard.mthings first."
}

New-Item -ItemType Directory -Force -Path $OutDir | Out-Null
$slaves = Import-Csv $csvPath

Write-Output "=== Modbus Slave: VelaGuard $($slaves.Count) slaves, COM$ComPort @ $Baud 8N1 ==="

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and register COM (run mbslave once as admin)."
}

$app.Connection = 0          # Serial
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0              # None (8N1, same as board / MThings)
$app.StopBits = 1
try { $app.Mode = 0 } catch {}  # RTU (if property exists)

$docs = @()
foreach ($s in $slaves) {
  $addr = [int]$s.addr
  $qty = [int]$s.holding_qty
  $name = $s.name
  $mbs = Join-Path $OutDir ("{0:D2}_{1}.mbs" -f $addr, (Get-SafeSensorName $name))
  # Remove legacy numbered name if present so the folder stays tidy.
  $legacy = Join-Path $OutDir ("velaguard_slave{0:D2}.mbs" -f $addr)
  if ((Test-Path $legacy) -and ($legacy -ne $mbs)) {
    Remove-Item -Force $legacy
  }

  $doc = New-Object -ComObject Mbslave.Document
  $ok = $doc.SetupHoldingRegisters($addr, 0, $qty)
  if (-not $ok) {
    throw "SetupHoldingRegisters failed addr=$addr qty=$qty"
  }

  $doc.EnableRefresh = $false
  $seedReg = [int]$s.seed_reg
  $seedVal = [int]$s.seed_value
  if ($seedReg -ge 0 -and $seedReg -lt $qty) {
    $doc.URegisters($seedReg) = $seedVal
  }
  # Give every slave a non-zero at reg0 unless addr=2 (first point at reg2).
  if ($addr -ne 2 -and $qty -gt 0) {
    $doc.URegisters(0) = 100 + $addr
  }

  try {
    $doc.Save($mbs)
  }
  catch {
    Write-Warning "COM Save not available for addr=$addr — save manually: $mbs"
  }

  if ($ShowWindows) {
    $doc.ShowWindow() | Out-Null
  }

  $docs += [pscustomobject]@{ Addr = $addr; Name = $name; Qty = $qty; File = $mbs; Doc = $doc }
  Write-Output ("addr={0,2} qty={1,2} first_reg={2} -> {3}" -f $addr, $qty, $s.first_reg, $mbs)
}

$connOk = $false
if ($OpenConnection) {
  # Empirically Mbslave may return 0 even when the serial port is usable.
  # Treat the call as best-effort; KeepOpen still holds the COM objects.
  $st = $app.OpenConnection()
  Write-Output "OpenConnection status=$st (holding docs regardless)"
  $connOk = $true
}

$msw = Join-Path $OutDir "velaguard.msw"
Write-Output ""
Write-Output "Next steps:"
Write-Output "  1. Close MThings (release COM$ComPort)"
Write-Output "  2. Modbus Slave: Connection -> Serial COM$ComPort, $Baud 8N1, Parity=None"
Write-Output "  3. Open all: .\scripts\open_velaguard_mbslaves.ps1   (or double-click open_velaguard_mbslaves.cmd)"
Write-Output "  4. File -> Save Workspace -> $msw  (one-time, reuse later)"
Write-Output "  5. Connection -> Connect"
Write-Output ""
Write-Output "Board: vgdiscover scan -a 1-32   or   vgscan -a 1-32"

$holdSec = $KeepOpenSeconds
if ($KeepOpen -and $holdSec -le 0) { $holdSec = 7200 }

if ($holdSec -gt 0) {
  if (-not $connOk -and $OpenConnection) {
    throw "Cannot KeepOpen: serial connection failed."
  }
  Write-Output ""
  Write-Output "Holding $($docs.Count) slave docs for ${holdSec}s (Ctrl+C to stop)..."
  try {
    Start-Sleep -Seconds $holdSec
  }
  finally {
    try { $app.CloseConnection() | Out-Null } catch {}
  }
}
elseif (-not $OpenConnection) {
  Write-Output ""
  Write-Output "Tip: add -OpenConnection -KeepOpenSeconds 3600 after COM port is free."
}

=== open_velaguard_mbslaves.ps1 ===
﻿# Open all 32 VelaGuard Modbus Slave windows (NN_<sensor>.mbs).
#
# IMPORTANT: Mbslave.Document COM windows are owned by this process. If the
# script exits, every window closes. This script ALWAYS holds until you press
# Enter (or -KeepOpenSeconds elapses).
#
# Usage:
#   .\open_velaguard_mbslaves.ps1
#   .\open_velaguard_mbslaves.ps1 -ComPort 4 -OpenConnection
#   .\open_velaguard_mbslaves.ps1 -Dir "$env:USERPROFILE\Documents\mthings"

param(
  [string]$Dir = "$env:USERPROFILE\Documents\mthings",
  [int]$ComPort = 4,
  [int]$Baud = 9600,
  [switch]$OpenConnection,
  [int]$KeepOpenSeconds = 0
)

$ErrorActionPreference = "Stop"

function Get-SafeSensorName([string]$Name) {
  $n = $Name -replace '^\[S\]', ''
  $n = $n.Trim()
  foreach ($c in @('<', '>', ':', '"', '/', '\', '|', '?', '*')) {
    $n = $n.Replace($c, '_')
  }
  $n = $n -replace '\s+', ''
  if ([string]::IsNullOrWhiteSpace($n)) { $n = 'sensor' }
  return $n
}

function Resolve-SlaveMbs([string]$Root, [int]$Addr, [string]$Name) {
  $safe = Get-SafeSensorName $Name
  $named = Join-Path $Root ("{0:D2}_{1}.mbs" -f $Addr, $safe)
  if (Test-Path $named) { return $named }
  $legacy = Join-Path $Root ("velaguard_slave{0:D2}.mbs" -f $Addr)
  if (Test-Path $legacy) { return $legacy }
  return $null
}

if (-not (Test-Path $Dir)) {
  throw "Directory not found: $Dir"
}
$Dir = (Resolve-Path $Dir).Path

$repoRoot = Split-Path -Parent $PSScriptRoot
$csvPath = Join-Path $repoRoot "config\modbus-slave\velaguard_slaves.csv"
# When this script lives in Documents\mthings, also try contest repo CSV.
if (-not (Test-Path $csvPath)) {
  $candidates = @(
    "$env:USERPROFILE\openvela\contest2026_004_TeamFalcons\config\modbus-slave\velaguard_slaves.csv",
    "\\wsl$\Ubuntu\home\hello19y\openvela\contest2026_004_TeamFalcons\config\modbus-slave\velaguard_slaves.csv",
    "\\wsl.localhost\Ubuntu\home\hello19y\openvela\contest2026_004_TeamFalcons\config\modbus-slave\velaguard_slaves.csv"
  )
  foreach ($c in $candidates) {
    if (Test-Path $c) { $csvPath = $c; break }
  }
}

$files = @()
if (Test-Path $csvPath) {
  foreach ($s in (Import-Csv $csvPath)) {
    $addr = [int]$s.addr
    $path = Resolve-SlaveMbs $Dir $addr $s.name
    if (-not $path) { throw "Missing mbs for addr=$addr under $Dir" }
    $files += [pscustomobject]@{ Addr = $addr; Name = $s.name; File = $path }
  }
}
else {
  $named = Get-ChildItem -Path $Dir -Filter "*.mbs" |
    Where-Object { $_.Name -match '^\d{2}_.+\.mbs$' } |
    Sort-Object Name
  if ($named.Count -eq 0) {
    throw "No NN_<sensor>.mbs in $Dir"
  }
  foreach ($f in $named) {
    $files += [pscustomobject]@{
      Addr = [int]$f.BaseName.Substring(0, 2)
      Name = $f.BaseName
      File = $f.FullName
    }
  }
}

$files = @($files | Sort-Object Addr)
Write-Output "=== Open $($files.Count) Modbus Slave docs from $Dir ==="
Write-Output "NOTE: keep this console open — closing it closes all slave windows."

try {
  $app = New-Object -ComObject Mbslave.Application
}
catch {
  throw "Mbslave.Application COM failed. Install Modbus Slave and run it once."
}

$app.Connection = 0
$app.SerialPort = $ComPort
$app.BaudRate = $Baud
$app.DataBits = 8
$app.Parity = 0
$app.StopBits = 1
try { $app.Mode = 0 } catch {}

# ArrayList keeps strong refs so RCW isn't GC'd mid-hold.
$docs = New-Object System.Collections.ArrayList
foreach ($f in $files) {
  $doc = New-Object -ComObject Mbslave.Document
  $ok = $false
  try { $ok = [bool]$doc.Open([string]$f.File) } catch {}
  if (-not $ok) {
    throw "Failed to open $($f.File)"
  }
  try { $doc.ShowWindow() | Out-Null } catch {}
  [void]$docs.Add($doc)
  Write-Output ("addr={0,2} opened {1}" -f $f.Addr, (Split-Path $f.File -Leaf))
}

if ($OpenConnection) {
  $st = $app.OpenConnection()
  Write-Output "OpenConnection status=$st (COM$ComPort @ $Baud 8N1)"
}
else {
  Write-Output ""
  Write-Output "Serial not opened by script. In Modbus Slave: Connection -> COM$ComPort @ $Baud 8N1 -> Connect"
  Write-Output "Or re-run with: -OpenConnection"
}

Write-Output ""
Write-Output "Holding $($docs.Count) windows alive via COM."
try {
  if ($KeepOpenSeconds -gt 0) {
    Write-Output "Auto-exit in ${KeepOpenSeconds}s (Ctrl+C sooner)..."
    Start-Sleep -Seconds $KeepOpenSeconds
  }
  else {
    Write-Host -ForegroundColor Yellow "Press Enter here when finished (windows will then close)."
    [void][System.Console]::ReadLine()
  }
}
finally {
  Write-Output "Releasing COM docs..."
  try { $app.CloseConnection() | Out-Null } catch {}
  for ($i = $docs.Count - 1; $i -ge 0; $i--) {
    try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($docs[$i]) } catch {}
  }
  try { [void][System.Runtime.InteropServices.Marshal]::FinalReleaseComObject($app) } catch {}
  [GC]::Collect()
  [GC]::WaitForPendingFinalizers()
}

=== maintenance_rtu_slave.ps1 ===
# Diagnostic Modbus RTU slave for the existing 14-point room scene.
# Only replies to board FC03/FC04 reads; never initiates bus traffic.
param(
  [string]$ComPort = 'COM4',
  [string]$ControlPath = '',
  [string]$LogPath = '',
  [switch]$EnableRts,
  [switch]$EnableDtr,
  [ValidateRange(1,168)][int]$Hours = 24,
  # Default to prompt replies so tests can expose receive timing defects.
  # Nonzero delays are only for explicit timing/timeout experiments.
  [ValidateRange(0,1000)][int]$ReplyDelayMs = 0
)
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [Text.Encoding]::UTF8
if (!$ControlPath) { $ControlPath = Join-Path $PSScriptRoot '../.debug/maintenance-slave-mode.txt' }
if (!$LogPath) { $LogPath = Join-Path $PSScriptRoot '../.debug/maintenance-slave.log' }
$ControlPath = [IO.Path]::GetFullPath($ControlPath)
$LogPath = [IO.Path]::GetFullPath($LogPath)
[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($LogPath)) | Out-Null
# Modes: normal, warn (temp=30 C), critical (temp=36 C), offline
# (all slave responses suppressed), offline1/2/12, critical_offline2, stop.
# Extra combinations are bounded voice evidence fixtures; the board remains
# the sole master and confirmed point configuration is unchanged.
if (!(Test-Path -LiteralPath $ControlPath)) { [IO.File]::WriteAllText($ControlPath,'normal') }
Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.IO.Ports;
using System.Diagnostics;
using System.Collections.Generic;
using System.Threading;
public static class VelaMaintenanceSlave {
 static ushort Crc(byte[] a,int n) { ushort c=0xffff; for(int i=0;i<n;i++){c^=a[i];for(int j=0;j<8;j++)c=(ushort)(((c&1)!=0)?(c>>1)^0xa001:c>>1);}return c; }
 static int Value(int slave,int reg,string mode) {
  if(slave==1&&reg==0)return mode.StartsWith("critical")?360:mode=="warn"?300:240;
  if(slave==1&&reg==1)return 500;
  if(slave==2&&reg==2)return 0;
  if(slave==3&&reg==0)return 10;
  if(slave==4&&reg==0)return 250;
  if(slave==4&&reg==1)return 240;
  if(slave==4&&reg==2)return 1;
  if(slave==5&&reg==0)return 400;
  if(slave==5&&reg==1)return 80;
  if(slave==5&&reg==2)return 0;
  if(slave==6&&reg==0)return 2300;
  if(slave==6&&reg==1)return 300;
  if(slave==6&&reg==2)return 1234;
  if(slave==7&&reg==0)return 0;
  if(slave==8&&reg==1)return 500;
  return -1;
 }
 public static void Run(string port,string control,string log,int hours,bool rts,bool dtr,int replyDelayMs) {
  using(var w=new StreamWriter(log,true,new System.Text.UTF8Encoding(false)))
  using(var p=new SerialPort(port,9600,Parity.None,8,StopBits.One)) {
   w.AutoFlush=true;p.ReadTimeout=100;p.WriteTimeout=1000;p.RtsEnable=rts;p.DtrEnable=dtr;p.Open();
   w.WriteLine("START {0:o} port={1} mode=slave-only baud=9600 rts={2} dtr={3} reply_delay_ms={4}",DateTime.Now,port,rts,dtr,replyDelayMs);
   var timer=Stopwatch.StartNew();var rx=new List<byte>();string mode="normal";long requests=0,replies=0,ignored=0,bad=0;int rawBudget=256;long next=0,refresh=0;
   try { while(timer.Elapsed.TotalHours<hours) {
    if(timer.ElapsedMilliseconds>=refresh) {
     try { string m=File.ReadAllText(control).Trim().ToLowerInvariant();
      if(m=="stop")break;
      if(m=="normal"||m=="warn"||m=="critical"||m=="offline"||m=="offline1"||m=="offline2"||m=="offline12"||m=="critical_offline2"){
       if(m!=mode)w.WriteLine("MODE {0:o} {1}",DateTime.Now,m);mode=m;
      }
     }catch(IOException){}refresh=timer.ElapsedMilliseconds+250;
    }
    int available=p.BytesToRead;
    if(available>0){byte[] chunk=new byte[available];int n=p.Read(chunk,0,chunk.Length);if(rawBudget>0){int sample=Math.Min(rawBudget,n);w.WriteLine("RX {0:o} {1}",DateTime.Now,BitConverter.ToString(chunk,0,sample));rawBudget-=sample;}for(int i=0;i<n;i++)rx.Add(chunk[i]);}
    while(rx.Count>=8){byte[] q=rx.GetRange(0,8).ToArray();ushort crc=Crc(q,6);
     if(q[6]!=(byte)crc||q[7]!=(byte)(crc>>8)){rx.RemoveAt(0);bad++;continue;}
     rx.RemoveRange(0,8);requests++;int s=q[0],fc=q[1],reg=(q[2]<<8)|q[3],qty=(q[4]<<8)|q[5];
     if(s<1||s>8||mode=="offline"||
        ((mode=="offline1"||mode=="offline12")&&s==1)||
        ((mode=="offline2"||mode=="offline12"||mode=="critical_offline2")&&s==2)){ignored++;continue;}
     byte error=0;if(fc!=3&&fc!=4)error=1;else if(qty<1||qty>125)error=3;
     if(error==0)for(int i=0;i<qty;i++)if(Value(s,reg+i,mode)<0){error=2;break;}
     byte[] response=error!=0?new byte[]{(byte)s,(byte)(fc|0x80),error,0,0}:new byte[5+qty*2];
     if(error==0){response[0]=(byte)s;response[1]=(byte)fc;response[2]=(byte)(qty*2);for(int i=0;i<qty;i++){int v=Value(s,reg+i,mode);response[3+i*2]=(byte)(v>>8);response[4+i*2]=(byte)v;}}
     crc=Crc(response,response.Length-2);response[response.Length-2]=(byte)crc;response[response.Length-1]=(byte)(crc>>8);
     if(replyDelayMs>0){Thread.Sleep(replyDelayMs);}
     p.Write(response,0,response.Length);replies++;
    }
    if(timer.ElapsedMilliseconds>=next){w.WriteLine("STATUS {0:o} elapsed_s={1:F1} mode={2} requests={3} replies={4} suppressed={5} crc_scan={6}",DateTime.Now,timer.Elapsed.TotalSeconds,mode,requests,replies,ignored,bad);next=timer.ElapsedMilliseconds+10000;}
    Thread.Sleep(2);
   }} finally {w.WriteLine("STOP {0:o} requests={1} replies={2} suppressed={3} crc_scan={4}",DateTime.Now,requests,replies,ignored,bad);}
  }
 }
}
'@
[VelaMaintenanceSlave]::Run($ComPort,$ControlPath,$LogPath,$Hours,$EnableRts.IsPresent,$EnableDtr.IsPresent,$ReplyDelayMs)

