1	# Host serial: batch-write VelaGuard point table via NSH vgpoint (COM3).
2	# Flow: add/set -> test -> wait for Enter -> apply --confirm -> list
3	#   powershell.exe -ExecutionPolicy Bypass -File scripts/vgpoint_host_apply.ps1
4	#   powershell.exe -ExecutionPolicy Bypass -File scripts/vgpoint_host_apply.ps1 -PointsFile scripts/vgpoint_demo_points.json
5	
6	param(
7	  [string]$ComPort = "COM3",
8	  [int]$Baud = 115200,
9	  [string]$PointsFile = ""
10	)
11	
12	$ErrorActionPreference = "Stop"
13	$script:pass = 0
14	$script:fail = 0
15	
16	if ($PointsFile -eq "") {
17	  $PointsFile = Join-Path $PSScriptRoot "vgpoint_demo_points.json"
18	}
19	
20	function Wait-Prompt {
21	  param([string]$Buf, [int]$TimeoutSec = 12)
22	  $deadline = (Get-Date).AddSeconds($TimeoutSec)
23	  while ((Get-Date) -lt $deadline) {
24	    if ($Buf -match "nsh>") { return $true }
25	    Start-Sleep -Milliseconds 120
26	  }
27	  return $false
28	}
29	
30	function Send-Serial {
31	  param(
32	    [System.IO.Ports.SerialPort]$Port,
33	    [string]$Cmd,
34	    [int]$WaitSec = 20
35	  )
36	  $Port.DiscardInBuffer()
37	  $Port.WriteLine($Cmd)
38	  Start-Sleep -Milliseconds 400
39	  $buf = ""
40	  $deadline = (Get-Date).AddSeconds($WaitSec)
41	  while ((Get-Date) -lt $deadline) {
42	    if ($Port.BytesToRead -gt 0) { $buf += $Port.ReadExisting() }
43	    if (Wait-Prompt $buf 1) { break }
44	    Start-Sleep -Milliseconds 120
45	  }
46	  $block = "`n=== $Cmd ===`n$buf"
47	  Write-Output $block
48	  return @{ Text = $buf; Block = $block }
49	}
50	
51	function Assert-Match {
52	  param([string]$Name, [string]$Hay, [string]$Pattern)
53	  if ($Hay -match $Pattern) {
54	    Write-Output "[PASS] $Name"
55	    $script:pass++
56	  } else {
57	    Write-Output "[FAIL] $Name (pattern: $Pattern)"
58	    $script:fail++
59	  }
60	}
61	
62	function Utf8Len {
63	  param([string]$Text)
64	  return [System.Text.Encoding]::UTF8.GetByteCount($Text)
65	}
66	
67	function Build-AddCmd {
68	  param($pt)
69	  $id = [string]$pt.id
70	  if ([string]::IsNullOrWhiteSpace($id)) {
71	    throw "point missing id"
72	  }
73	  $addr = [int]$pt.addr
74	  $reg = [int]$pt.reg
75	  $cmd = "vgpoint add -i $id -a $addr -r $reg"
76	  if ($null -ne $pt.fc) { $cmd += " -f $([int]$pt.fc)" }
77	  if ($null -ne $pt.qty) { $cmd += " -q $([int]$pt.qty)" }
78	  if ($null -ne $pt.dtype -and "$($pt.dtype)" -ne "") { $cmd += " -d $($pt.dtype)" }
79	  if ($null -ne $pt.scale) { $cmd += " -s $($pt.scale)" }
80	  if ($null -ne $pt.unit -and "$($pt.unit)" -ne "") { $cmd += " -u $($pt.unit)" }
81	  if ($null -ne $pt.cmp -and "$($pt.cmp)" -ne "") { $cmd += " -k $($pt.cmp)" }
82	  if ($null -ne $pt.warn) { $cmd += " -w $($pt.warn)" }
83	  if ($null -ne $pt.crit) { $cmd += " -C $($pt.crit)" }
84	  if ($null -ne $pt.fail_n) { $cmd += " -n $([int]$pt.fail_n)" }
85	  $name = [string]$pt.name
86	  $nameCmd = $null
87	  if ($name -ne "") {
88	    $withName = "$cmd -N $name"
89	    if ((Utf8Len $withName) -le 120) {
90	      $cmd = $withName
91	    } else {
92	      $nameCmd = "vgpoint set $id -N $name"
93	      if ((Utf8Len $nameCmd) -gt 120) {
94	        throw "name command longer than 120 bytes: $nameCmd"
95	      }
96	    }
97	  }
98	  if ((Utf8Len $cmd) -gt 120) {
99	    throw "command longer than 120 bytes: $cmd"
100	  }
101	  return @{ Add = $cmd; NameSet = $nameCmd; Id = $id }
102	}
103	
104	if (-not (Test-Path $PointsFile)) {
105	  throw "points file not found: $PointsFile"
106	}
107	
108	$json = Get-Content -Raw -Path $PointsFile | ConvertFrom-Json
109	$points = @()
110	if ($null -ne $json.points) { $points = @($json.points) }
111	elseif ($json -is [System.Array]) { $points = @($json) }
112	if ($points.Count -lt 1) {
113	  throw "no points in $PointsFile"
114	}
115	
116	$port = New-Object System.IO.Ports.SerialPort
117	$port.PortName = $ComPort
118	$port.BaudRate = $Baud
119	$port.ReadTimeout = 8000
120	$port.NewLine = "`n"
121	$port.Encoding = [System.Text.Encoding]::UTF8
122	
123	try {
124	  $port.Open()
125	  Start-Sleep -Seconds 3
126	  $boot = ""
127	  $bootDeadline = (Get-Date).AddSeconds(20)
128	  while ((Get-Date) -lt $bootDeadline) {
129	    if ($port.BytesToRead -gt 0) { $boot += $port.ReadExisting() }
130	    if ($boot -match "nsh>") { break }
131	    Start-Sleep -Milliseconds 200
132	  }
133	  while ($port.BytesToRead -gt 0) { [void]$port.ReadExisting(); Start-Sleep -Milliseconds 50 }
134	
135	  $r = Send-Serial $port "?" 8
136	  Assert-Match "vgpoint in help" $r.Text "vgpoint"
137	
138	  foreach ($pt in $points) {
139	    $built = Build-AddCmd $pt
140	    $add = $built.Add
141	    $id = $built.Id
142	    $r = Send-Serial $port $add 12
143	    if ($r.Text -match "code=dup_id") {
144	      $set = ($add -replace "^vgpoint add -i $id ", "vgpoint set $id ")
145	      $r = Send-Serial $port $set 12
146	      Assert-Match "set $id" $r.Text "vgpoint: OK cmd=set"
147	    } else {
148	      Assert-Match "add $id" $r.Text "vgpoint: OK cmd=add"
149	    }
150	    if ($null -ne $built.NameSet) {
151	      $r = Send-Serial $port $built.NameSet 12
152	      Assert-Match "set name $id" $r.Text "vgpoint: OK cmd=set"
153	    }
154	  }
155	
156	  $r = Send-Serial $port "vgpoint test" 45
157	  Assert-Match "test READ or fail token" $r.Text "vgpoint: READ |code=test_fail|code=no_candidate|code=bus_busy"
158	  Write-Output $r.Text
159	
160	  Write-Host ""
161	  Write-Host "Candidate test finished. Review READ lines above."
162	  Write-Host "Press Enter to send: vgpoint apply --confirm"
163	  [void](Read-Host)
164	
165	  $r = Send-Serial $port "vgpoint apply --confirm" 15
166	  Assert-Match "apply confirm" $r.Text "vgpoint: OK cmd=apply table=committed"
167	
168	  $r = Send-Serial $port "vgpoint list" 12
169	  Assert-Match "list committed" $r.Text "vgpoint: OK cmd=list table=committed"
170	
171	  Write-Output "`n[vgpoint_host_apply] pass=$($script:pass) fail=$($script:fail)"
172	  if ($script:fail -gt 0) { exit 1 }
173	}
174	catch {
175	  Write-Error "vgpoint_host_apply failed: $($_.Exception.Message)"
176	  exit 1
177	}
178	finally {
179	  if ($port.IsOpen) { $port.Close() }
180	}
