            r[4 + i * 2] = (byte)(vals[i] & 0xff);
        }
        ushort c = Crc(r, r.Length - 2);
        r[r.Length - 2] = (byte)c;
        r[r.Length - 1] = (byte)(c >> 8);
        return r;
    }

